from lib import *
S = SS('c5')
steps = [
    step("ENTRYPOINT 与 CMD 的组合,最终执行的命令(docker create 之后 docker inspect 的 Path 与 Args)。[1] ENTRYPOINT [\"/e.sh\"] + CMD [\"a\",\"b\"]:Path=/e.sh,Args=[\"a\",\"b\"];[2] 同上,docker run 后面加参数 x:Args=[\"x\"](只替换了 CMD);[3] 用 --entrypoint echo:Path=echo,Args=[\"new\"];[4] shell 形式 ENTRYPOINT /e.sh + CMD [\"a\",\"b\"]:Path=/bin/sh,Args=[\"-c\",\"/e.sh\",\"a\",\"b\"],脚本收到 0 个参数(CMD 的 a、b 变成了 sh 的位置参数,被忽略);[5] exec 形式 ENTRYPOINT + shell 形式 CMD echo hello:Args=[\"/bin/sh\",\"-c\",\"echo hello\"],脚本收到 3 个参数;[6] 只有 CMD [\"echo\",\"from cmd\"]:Path=echo;[7] 同上,run 时给 ls /etc/alpine-release:整个 CMD 被替换,Path=ls;[8] shell 形式 CMD:Path=/bin/sh,Args=[\"-c\",\"echo from shell cmd\"];[9] ENTRYPOINT [\"/e.sh\",\"fixed\"] + CMD [\"default\"],run 时给 over:Args=[\"fixed\",\"over\"]。", t=tl(S(1)), done=lidx(S(1), '[1]', '[2]', '[3]', '[6]', '[7]', '[9]'), mark=lidx(S(1), '[4]', '[5]', '[8]'), kv=KV([['docker run 后的参数', '替换 CMD,不替换 ENTRYPOINT'], ['--entrypoint', '覆盖 ENTRYPOINT'], ['shell 形式 ENTRYPOINT', 'CMD 变成 sh -c 的位置参数,基本被忽略'], ['exec 形式 ENTRYPOINT + shell 形式 CMD', 'CMD 的 /bin/sh -c … 作为参数交给入口程序']], ['shell 形式 ENTRYPOINT'])),
    step("容器里 PID 1 到底是谁(alpine 的 /bin/sh 是 busybox ash):ENTRYPOINT [\"sleep\",\"300\"]:ps 看到 1 sleep 300;ENTRYPOINT sleep 300(shell 形式):也是 1 sleep 300——sh -c 只有一条命令时直接 exec 了它;ENTRYPOINT sleep 300 && echo done:1 是 /bin/sh -c sleep 300 && echo done,sleep 300 成了 PID 7 的子进程。", t=tl(S(2)), done=lidx(S(2), '["sleep", "300"]', 'ENTRYPOINT sleep 300]'), mark=lidx(S(2), '&& echo done'), kv=KV([['exec 形式', 'PID 1 是你的程序'], ['shell 形式,单条命令', '这个 busybox ash 里被 exec,PID 1 仍是程序'], ['shell 形式,复合命令', 'PID 1 是 sh,程序是它的子进程']], ['shell 形式,复合命令'])),
]
A = mkartc('c5', 5, 'Docker,ENTRYPOINT,CMD,exec形式,shell形式,真实验证,动画演示',
    '在 Docker Engine 29.8.2 里实测 ENTRYPOINT 与 CMD 的 9 种组合(用 docker create + inspect 的 Path/Args 看最终命令):docker run 后的参数只替换 CMD;--entrypoint 覆盖入口;shell 形式的 ENTRYPOINT 会让 CMD 变成 sh -c 的位置参数而被脚本忽略;exec 形式入口 + shell 形式 CMD 时入口收到 /bin/sh -c …;以及 PID 1 在 exec 形式、单条 shell 命令、复合 shell 命令下各是谁。',
    'ENTRYPOINT 和 CMD 的搭配规则用文字很难记。这篇不背规则,直接把九种写法都跑出来,看容器最终执行的 Path 和 Args,再看 shell 形式对 PID 1 的影响。',
    [('只换 CMD', 'docker run 镜像名后面的参数替换 CMD,ENTRYPOINT 保留(Args=["x"])'), ('收到 0 个参数', 'shell 形式的 ENTRYPOINT 加 CMD ["a","b"] 时,入口脚本拿到的参数个数'), ('PID 1 = sh', 'ENTRYPOINT 是复合 shell 命令(sleep 300 && echo done)时的 PID 1')],
    [('九种组合', '<p>exec 形式的 <code>ENTRYPOINT</code> 会把 <code>CMD</code>(或 <code>docker run</code> 后面的参数)追加成它的参数;<code>docker run</code> 给了参数就整体替换 <code>CMD</code>;<code>--entrypoint</code> 直接覆盖入口。只有 <code>CMD</code> 时,run 后面的命令整个替换它。</p>'),
     ('shell 形式的坑与 PID 1', '<p><code>ENTRYPOINT /e.sh</code> 被存成 <code>["/bin/sh","-c","/e.sh"]</code>,<code>CMD ["a","b"]</code> 只是 <code>sh -c</code> 的位置参数,脚本收到 0 个参数。<code>CMD</code> 用 shell 形式、<code>ENTRYPOINT</code> 用 exec 形式时,入口收到的是 <code>/bin/sh -c "echo hello"</code> 三个参数,通常不是你想要的。PID 1:exec 形式时就是你的程序;shell 形式 + 单条命令,这个 busybox <code>sh</code> 把它直接 <code>exec</code> 了,PID 1 仍是程序(别的 shell 不一定);复合命令(<code>&amp;&amp;</code>)时 PID 1 是 <code>/bin/sh</code>,你的程序是子进程,信号处理就不同了——后面讲 PID 1 与信号的文章会继续验证。</p>')],
    steps,
    [ENV_C + '。每种组合是一个单独构建的镜像(alpine:3.20 + 一个打印参数的脚本),用 docker create 之后 docker inspect 取 .Path / .Args,并 docker start -a 看输出;PID 1 通过 docker exec ps 查看;实验后已删除所有镜像和容器',
     '没有验证:bash / dash 等其它 shell 的 exec 优化、docker compose 的 entrypoint / command 覆盖、ENTRYPOINT 为空数组的写法、CMD 在 ENTRYPOINT 之前声明的顺序影响、SHELL 指令改默认 shell 的效果'],
    'ENTRYPOINT 与 CMD')
